#!/usr/bin/env node

"use strict";

const execSync = require("child_process").execSync;
const fs = require("fs");
const parseArgs = require("minimist");

let args = process.argv.slice(2);
let argv = parseArgs(args);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help                print this message");
    console.log("  --image FILE             path to ext4 image file");
    console.log("  --outfile FILE           path to output package file");
    console.log("  --preinstall FILE        path to preinstall executable");
    console.log("  --postinstall FILE       path to postinstall executable");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

if (!argv.outfile) {
    console.log("ERROR: outfile not specified");
    usage();
    process.exit(1);
}

function copySync(src, dest) {
    execSync("cp -a " + src + " " + dest);
    execSync("chmod 755 " + dest);
}

function make_pkg() {
    fs.mkdirSync("./pkg");
    if (argv.image) {
        fs.mkdirSync("./mnt");
        execSync("mount -o loop " + argv.image + " ./mnt");
        execSync("tar -C ./mnt -cjf ./pkg/filesystem.tar.bz2 .");
        execSync("umount ./mnt");
        fs.rmdirSync("./mnt");
    }
    if (argv.preinstall) {
        copySync(argv.preinstall, "./pkg/preinstall");
    }
    if (argv.postinstall) {
        copySync(argv.postinstall, "./pkg/postinstall");
    }
    execSync("tar -C ./pkg -cf " + argv.outfile + " .");
    if (argv.image) {
        fs.unlinkSync("./pkg/filesystem.tar.bz2");
    }
    if (argv.preinstall) {
        fs.unlinkSync("./pkg/preinstall");
    }
    if (argv.postinstall) {
        fs.unlinkSync("./pkg/postinstall");
    }
    fs.rmdirSync("./pkg");
}

try {
    make_pkg();
} catch (error) {
    console.log("ERROR:", error);
    process.exit(1);
}
